def tightest_sizes(ranges: list[list[int]], points: list[int]) -> list[int]:
    out = []
    for p in points:
        best = -1
        for s, e in ranges:                  # every range, for every point
            if s <= p <= e and (best == -1 or e - s + 1 < best):
                best = e - s + 1
        out.append(best)
    return out
